class Solution {
    public int maximumSum(int[] arr){
        int keep=arr[0],removed=Integer.MIN_VALUE/2,answer=arr[0];
        for(int i=1;i<arr.length;i++){
            int nextRemoved=Math.max(removed+arr[i],keep);
            int nextKeep=Math.max(arr[i],keep+arr[i]);
            keep=nextKeep;
            removed=nextRemoved;
            answer=Math.max(answer,Math.max(keep,removed));
        }
        return answer;
    }
}

code.kotlin:
class Solution {
    fun maximumSum(arr:IntArray):Int{
        var keep=arr[0];
        var removed=Int.MIN_VALUE/2;
        var answer=arr[0];
        for(i in 1 until arr.size){
            val nextRemoved=maxOf(removed+arr[i],keep);
            val nextKeep=maxOf(arr[i],keep+arr[i]);
            keep=nextKeep;
            removed=nextRemoved;
            answer=maxOf(answer,keep,removed)
        };
        return answer
    }
}

code.cpp:
class Solution {
    public: int maximumSum(vector<int>& arr){
        int keep=arr[0],removed=INT_MIN/2,answer=arr[0];
        for(int i=1;i<(int)arr.size();++i){
            int nextRemoved=max(removed+arr[i],keep),nextKeep=max(arr[i],keep+arr[i]);
            keep=nextKeep;
            removed=nextRemoved;
            answer=max({
                answer,keep,removed
            });
        }
        return answer;
    }
};
